#!/usr/bin/env python3
"""Deny recursive subagent births while leaving root-agent dispatch untouched.

The global throughput agreement authorizes roots to fill the shared LOOP
capacity.  A worker/verifier/reviewer is a leaf: allowing every leaf to apply
the same agreement recursively creates a 16x16 birth cascade.  This hook uses
the immutable rollout session_meta parent_thread_id as the authority.  It
does not cap root concurrency and does not terminate existing work.
"""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any


SPAWN_NAMES = ("spawn_agent", "create_thread", "fork_thread")


def is_spawn_tool(name: Any) -> bool:
    """Match Desktop and CLI spawn names, including compact ``Agent``.

    Official PreToolUse matchers see ``spawn_agent`` as ``Agent``. Folding out
    non-alphanumerics makes ``spawnAgent`` and ``multi_agent_v1__spawn_agent``
    equivalent. ``close_agent`` must not match.
    """
    raw = str(name or "")
    value = raw.casefold()
    if any(item in value for item in SPAWN_NAMES):
        return True
    folded = "".join(ch for ch in value if ch.isalnum())
    return folded in {"spawnagent", "createthread", "forkthread", "agent"} or (
        "spawnagent" in folded
    )


def is_spawn_agent_tool(name: Any) -> bool:
    """True for spawn_agent / Agent; create_thread and fork_thread stay out."""
    if not is_spawn_tool(name):
        return False
    folded = "".join(ch for ch in str(name or "").casefold() if ch.isalnum())
    if folded in {"createthread", "forkthread"}:
        return False
    if ("createthread" in folded or "forkthread" in folded) and "spawnagent" not in folded:
        return False
    return True


def session_is_child(session_id: Any, sessions: Path) -> bool:
    value = str(session_id or "").strip()
    if not value or not sessions.exists():
        return False
    matches = sorted(sessions.rglob("rollout-*%s*.jsonl" % value),
                     key=lambda path: path.stat().st_mtime, reverse=True)
    for path in matches:
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    try:
                        row = json.loads(line)
                    except ValueError:
                        continue
                    if row.get("type") != "session_meta":
                        continue
                    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                    parent = payload.get("parent_thread_id")
                    if not parent:
                        source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
                        subagent = source.get("subagent") if isinstance(source.get("subagent"), dict) else {}
                        spawn = subagent.get("thread_spawn") if isinstance(subagent.get("thread_spawn"), dict) else {}
                        parent = spawn.get("parent_thread_id") or spawn.get("parent_session_id")
                    return bool(parent)
        except OSError:
            continue
    return False


def decision(payload: dict[str, Any], sessions: Path) -> dict[str, Any] | None:
    if not is_spawn_tool(payload.get("tool_name") or payload.get("tool") or payload.get("name")):
        return None
    session_id = payload.get("session_id") or payload.get("thread_id")
    marked_leaf = os.environ.get("LOOP_LEAF_AGENT", "").strip() == "1"
    if not marked_leaf and not session_is_child(session_id, sessions):
        return None
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": (
            "LOOP leaf agents cannot recursively spawn agents. Return the bounded "
            "result to the root orchestrator; the root owns shared global-60 refill."
        ),
    }}


def main() -> int:
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        payload = {}
    sessions = Path(os.environ.get(
        "CODEX_SESSIONS_DIR",
        str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
    )).resolve()
    try:
        result = decision(payload if isinstance(payload, dict) else {}, sessions)
    except Exception as exc:  # backstop: an ambiguous gate must fail CLOSED
        sys.stderr.write("leaf_spawn_gate crashed (%r); denying spawn\n" % (exc,))
        result = {"hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": (
                "spawn gate internal error — ambiguous births fail closed "
                "per LOOP routing invariant. Retry the spawn; if it persists, "
                "inspect data/governor/ gate logs."),
        }}
    if result is not None:
        print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Fail closed when a LOOP root attempts an ambiguous child birth.

The configured default child model is defence in depth, not authorization.
Every ordinary Desktop child must be born with an explicit LOOP role, the
role-specific model and effort from the active model profile, and an
independent context.
"""
from __future__ import annotations

import json
import os
import sys
import tomllib
from pathlib import Path
from typing import Any

from leaf_agent_spawn_gate import is_spawn_agent_tool, is_spawn_tool, session_is_child


PROFILE_PATH = Path(__file__).resolve().parents[1] / "config" / "model_profiles.toml"
QUARANTINE_PATH = Path(__file__).resolve().parents[1] / "data" / "governor" / "quarantined_models.json"
EXECUTION_ROLES = frozenset({"worker", "duty_officer"})
REVIEW_ROLES = frozenset({"verifier", "reviewer", "plan_expander"})
APPROVED_ROLES = EXECUTION_ROLES | REVIEW_ROLES
APPROVED_EFFORTS = frozenset({"low", "medium", "high", "xhigh", "max", "ultra"})
def approved_route(role: str, profile_path: Path | None = None) -> tuple[str, str]:
    """Return the active profile route for *role*, failing closed on drift."""
    profile_path = PROFILE_PATH if profile_path is None else profile_path
    try:
        doc = tomllib.loads(profile_path.read_text(encoding="utf-8"))
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise ValueError(f"cannot load {profile_path}: {exc}") from exc

    active = doc.get("active_profile")
    profiles = doc.get("profiles")
    if not isinstance(active, str) or not active.strip() or not isinstance(profiles, dict):
        raise ValueError("active_profile or profiles table is missing")
    profile = profiles.get(active)
    if not isinstance(profile, dict):
        raise ValueError(f"active profile {active!r} is missing")

    if role in EXECUTION_ROLES:
        model_key, effort_key = "execution_model", "execution_reasoning"
    elif role in REVIEW_ROLES:
        model_key, effort_key = "review_model", "review_reasoning"
    else:
        raise ValueError(f"role {role!r} is not approved")

    model = profile.get(model_key)
    effort = profile.get(effort_key)
    if not isinstance(model, str) or "/" not in model or not model.strip():
        raise ValueError(f"{model_key} is invalid in active profile {active!r}")
    if not isinstance(effort, str) or effort.casefold() not in APPROVED_EFFORTS:
        raise ValueError(f"{effort_key} is invalid in active profile {active!r}")
    return model.strip(), effort.casefold()


def deny(reason: str) -> dict[str, Any]:
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": "LOOP root spawn denied: " + reason,
    }}


def model_is_quarantined(model: str) -> bool:
    try:
        doc = json.loads(QUARANTINE_PATH.read_text(encoding="utf-8"))
        item = (doc.get("models") or {}).get(model) or {}
        return item.get("status") == "quarantined"
    except (OSError, ValueError, AttributeError):
        return False


def decision(payload: dict[str, Any], sessions: Path) -> dict[str, Any] | None:
    tool_name = str(payload.get("tool_name") or payload.get("tool") or payload.get("name") or "")
    if not is_spawn_tool(tool_name):
        return None
    if not is_spawn_agent_tool(tool_name):
        # create_thread / fork_thread skip model pinning.
        return None
    session_id = payload.get("session_id") or payload.get("thread_id")
    if os.environ.get("LOOP_LEAF_AGENT", "").strip() == "1" or session_is_child(session_id, sessions):
        # The dedicated leaf gate owns this case and denies all descendants.
        return None
    arguments = payload.get("tool_input")
    if not isinstance(arguments, dict):
        return deny("tool_input is absent or malformed; ambiguous births fail closed")

    role = str(arguments.get("agent_type") or "").strip().casefold()
    if not role or role == "default":
        return deny("agent_type must be an explicit LOOP role; roleless/default is prohibited")
    if role not in APPROVED_ROLES:
        return deny(f"agent_type={role!r} is not an approved LOOP child role")

    try:
        approved_model, approved_effort = approved_route(role)
    except ValueError as exc:
        return deny(f"active model profile is unavailable or invalid: {exc}")

    model = str(arguments.get("model") or "").strip()
    if model_is_quarantined(model):
        return deny(f"model {model} is quarantined and cannot spawn")
    if model != approved_model:
        return deny(f"model must be explicitly pinned to {approved_model} for role {role}")

    effort = str(arguments.get("reasoning_effort") or "").strip().casefold()
    if effort != approved_effort:
        return deny(
            f"reasoning_effort must be explicitly pinned to {approved_effort} for role {role}"
        )

    if arguments.get("fork_context") is True:
        return deny("fork_context=true is prohibited; LOOP children use independent context")
    return None


def main() -> int:
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        payload = {}
    sessions = Path(os.environ.get(
        "CODEX_SESSIONS_DIR",
        str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
    )).resolve()
    try:
        result = decision(payload if isinstance(payload, dict) else {}, sessions)
    except Exception as exc:  # backstop: an ambiguous gate must fail CLOSED
        sys.stderr.write("root_spawn_gate crashed (%r); denying spawn\n" % (exc,))
        result = {"hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": (
                "spawn gate internal error — ambiguous births fail closed "
                "per LOOP routing invariant. Retry the spawn; if it persists, "
                "inspect data/governor/ gate logs."),
        }}
    if result is not None:
        print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Mode router for the v1/v2 Sol PreToolUse gates.

cold_start enforces v1; shadow enforces v1 and records the v2 counterfactual;
layered enforces v2.  A single routing.mode edit rolls back immediately.
"""
from __future__ import annotations

import hashlib
import json
import os
import subprocess
import sys
import time
import tomllib
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "harness"))
from orchestration_common import layered_authorization  # noqa: E402

GATED_PREFIXES = ("shell", "shell_command", "bash", "local_shell",
                  "exec_command", "functions.exec", "run_terminal", "terminal",
                  "web_search", "search", "grep", "glob", "mcp__",
                  "read_mcp_resource", "list_mcp", "read_many_files",
                  "read_file", "list_files", "pytest", "test")


def find_root(payload: dict) -> Path | None:
    explicit = os.environ.get("LOOP_ROOT")
    if explicit:
        candidate = Path(explicit).resolve()
        if (candidate / "config" / "orchestration_policy_v2.toml").exists():
            return candidate
    start = Path(payload.get("cwd") or os.getcwd()).resolve()
    for candidate in (start, *start.parents):
        if (candidate / "config" / "orchestration_policy_v2.toml").exists():
            return candidate
    # The saved Desktop project is the package parent (E:/codex-LOOP), while
    # the policy-bearing implementation is its canonical codex-loop-s-f2
    # child.  Recognize only this exact package relation; unrelated cwd values
    # still pass through.
    package = Path(__file__).resolve().parents[1]
    if start == package.parent and (
            package / "config" / "orchestration_policy_v2.toml").exists():
        return package
    # A user-level installation also receives hooks for unrelated projects.
    # No policy ancestor means this is not a LOOP operation: pass through
    # instead of silently applying the package root's policy to another cwd.
    return None


def read_mode(root: Path) -> str:
    path = root / "config" / "orchestration_policy_v2.toml"
    with path.open("rb") as handle:
        doc = tomllib.load(handle)
    mode = str(doc.get("routing", {}).get("mode", "cold_start"))
    if mode not in ("cold_start", "shadow", "layered"):
        raise ValueError("invalid routing.mode %r" % mode)
    return mode


def invoke(script: Path, raw: str) -> tuple[int, str, str]:
    env = os.environ.copy()
    env["LOOP_ROOT"] = str(script.resolve().parents[1])
    proc = subprocess.run([sys.executable, str(script)], input=raw,
                          text=True, capture_output=True, timeout=8, env=env)
    return proc.returncode, proc.stdout, proc.stderr


def append_shadow(root: Path, payload: dict, v1: tuple[int, str, str],
                  v2: tuple[int, str, str]) -> None:
    path = root / "data" / "governor" / "hook_shadow.ndjsonl"
    path.parent.mkdir(parents=True, exist_ok=True)
    record = {
        "ts": time.time(), "event": "hook_shadow_decision",
        "tool": payload.get("tool_name"),
        "payload_hash": hashlib.sha256(json.dumps(
            payload, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:24],
        "v1_rc": v1[0], "v1_deny": bool(v1[1].strip()),
        "v2_rc": v2[0], "v2_deny": bool(v2[1].strip()),
        "agree": (v1[0] == v2[0] and bool(v1[1].strip()) ==
                  bool(v2[1].strip())),
    }
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, sort_keys=True) + "\n")


def deny(reason: str) -> str:
    return json.dumps({"hookSpecificOutput": {
        "hookEventName": "PreToolUse", "permissionDecision": "deny",
        "permissionDecisionReason": reason}})


def layered_authorized(root: Path) -> bool:
    return layered_authorization(root)[0]


def main() -> int:
    raw = sys.stdin.read()
    try:
        payload = json.loads(raw) if raw.strip() else {}
    except ValueError:
        payload = {}
    if not payload:
        return 0
    root = find_root(payload)
    if root is None:
        return 0
    try:
        mode = read_mode(root)
    except Exception as exc:
        # The installed cold-start gate is the rollback authority.  A broken
        # v2 policy must not silently select layered behavior.
        sys.stderr.write("sol_tool_gate_router: policy unreadable (%s); cold_start\n" % exc)
        mode = "cold_start"
    v1_script = root / "hooks" / "sol_tool_gate.py"
    # RootTurnGovernor is the single v2 implementation.  The old
    # sol_tool_gate_v2.py remains historical/rollback evidence only.
    v2_script = root / "harness" / "root_turn_governor.py"
    try:
        if mode == "cold_start":
            rc, out, err = invoke(v1_script, raw)
            if err:
                sys.stderr.write(err)
            if rc != 0:
                sys.stderr.write("sol_tool_gate_router: v1 gate rc=%d, fail-open rollback\n" % rc)
                return 0
            if out:
                sys.stdout.write(out)
            return 0
        if mode == "shadow":
            v1 = invoke(v1_script, raw)
            v2 = invoke(v2_script, raw)
            append_shadow(root, payload, v1, v2)
            if v1[2]:
                sys.stderr.write(v1[2])
            if v1[0] == 0 and v1[1]:
                sys.stdout.write(v1[1])
            return 0
        tool = str(payload.get("tool_name") or "").lower()
        if tool.startswith(GATED_PREFIXES) and not layered_authorized(root):
            print(deny("layered mode lacks a fresh full gate authorization; "
                       "run layered_gate.py enable or set routing.mode=cold_start"))
            return 0
        rc, out, err = invoke(v2_script, raw)
        if err:
            sys.stderr.write(err)
        if rc != 0:
            print(deny("v2 Sol gate failed rc=%d — layered mode fails closed; "
                       "set routing.mode=cold_start to roll back" % rc))
        elif out:
            sys.stdout.write(out)
        return 0
    except (OSError, subprocess.SubprocessError) as exc:
        if mode == "layered":
            print(deny("v2 Sol gate unavailable (%s) — layered mode fails closed; "
                       "set routing.mode=cold_start to roll back" % exc))
        else:
            sys.stderr.write("sol_tool_gate_router: %s (rollback mode fail-open)\n" % exc)
        return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""sol_tool_gate_v2.py — fail-closed, externally-attested root-turn governor.

Supersedes ``hooks/sol_tool_gate.py`` and fixes P0-5
(``phase1b_codebase_analysis.md``): the v1 gate failed **open** on every
error, exempted any session whose ledger was empty ("planning" forever), and
honored a ``loop_state`` key written *by the very session it constrains* —
the constrained party controlled its own exemption switch.

v2 inverts every one of those properties (design §2.5):

1. **Fail-closed** — an unreadable ledger, a STALE/MISSING meter report, or
   any internal error **denies** gated tools for non-planning states, with a
   ``governor.fail_closed`` audit event. Plain conversation and
   packet/dispatch tools are never gated, so "decompose and dispatch" is
   always available.
2. **No self-control** — an explicit ``loop_state`` ledger key is honored
   only when accompanied by a matching attestation appended through the
   harness CLI (``loop_state_set`` writes ``governor.state_set`` records into
   ``data/governor/state_attestations.ndjsonl`` with a reason + idempotency
   key). A bare key is ignored and flagged
   (``governor.state_key_unattested``).
3. **Bounded planning lease** — "planning" derived from an empty ledger
   carries a lease (``planning_max_turns`` / ``planning_max_new_tokens``
   without a packet-creation event). On expiry, gated tools are denied with
   the actionable reason "decompose or dispatch".
4. **Budget actuation at the right boundary** — the gate reads meter v2
   (:mod:`model_token_share_v2`): budget state ``HIGH`` (5h hysteresis) or a
   critical per-root 1h share denies non-exempt gated calls with an
   actionable delegate instruction. This finally binds the actual token
   consumer: root-session *turns*, not Sol-model dispatches (a null set).
5. **Audit everything** — every decision (allow *and* deny) is appended to
   ``data/governor/gate_decisions.ndjsonl``. Break-glass
   (``LOOP_GOVERNOR_OVERRIDE=<reason>``) allows a bypass but appends a
   ``governor.break_glass`` event per call — observable, never silent.

Model families come from ``config/orchestration_policy_v2.toml [models]`` —
the Sol model is **not hardcoded** (execution currently uses V4 Flash).

Hook contract: PreToolUse payload (one JSON object) on stdin; deny emits
``hookSpecificOutput.permissionDecision = "deny"`` on stdout; exit 0 always
(the *decision*, not the exit code, carries the outcome).
"""

from __future__ import annotations

import json
import logging
import os
import sys
import tempfile
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Final, Mapping, Sequence

__all__ = [
    "GATED_TOOL_PREFIXES",
    "GateDecision",
    "SolToolGateV2",
    "main",
]

LOG = logging.getLogger("sol_tool_gate_v2")

# Tool names (lowercased, prefix-matched) that constitute L0 data processing
# when issued from the root Sol session. Packet/dispatch tools are absent by
# design: delegation must always remain available (fail-closed escape hatch).
GATED_TOOL_PREFIXES: Final[tuple[str, ...]] = (
    "shell", "shell_command", "bash", "local_shell", "exec_command",
    "functions.exec", "run_terminal", "terminal", "web_search", "search",
    "grep", "glob", "mcp__", "read_mcp_resource", "list_mcp",
    "read_many_files", "read_file", "list_files", "pytest", "test",
)

_ADJUDICATION_STATES: Final[frozenset[str]] = frozenset(
    {"SOL_ADJUDICATE", "DEAD_LETTER", "MERGE_CONFLICT", "WAVE_DONE",
     "WAVE_DONE_READY", "SOL_WAKE"})
_TERMINAL_STATES: Final[frozenset[str]] = frozenset({"MERGED", "DONE"})
# Approved LOOP child roles (upstream v1 semantics): an explicit role label
# marks the session as a dispatch target regardless of its physical model.
# This keeps identity decidable while the root and execution temporarily
# share one model pin.
_CHILD_ROLES: Final[frozenset[str]] = frozenset(
    {"worker", "verifier", "reviewer", "plan_expander", "duty_officer",
     "explorer"})
# K3 work states count as EXECUTION — K3 work must never re-open Sol's tool
# window (design §7 loop-state derivation update).
_EXECUTION_EXTRA: Final[frozenset[str]] = frozenset(
    {"EXPAND_K3", "L2_VERIFY", "L2_RANK"})


@dataclass(frozen=True)
class GateDecision:
    """Structured outcome of one gate evaluation."""

    allow: bool
    reason: str
    state: str | None = None
    rule: str = ""
    break_glass: bool = False

    def to_hook_output(self) -> str | None:
        """PreToolUse deny JSON, or ``None`` when allowed."""
        if self.allow:
            return None
        return json.dumps({"hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": self.reason}})


def _load_policy(policy_path: Path) -> dict[str, Any]:
    """Fail-closed TOML load (tomllib; minimal fallback on 3.10)."""
    text = policy_path.read_text(encoding="utf-8")  # OSError propagates
    try:
        import tomllib
        return tomllib.loads(text)
    except ModuleNotFoundError:
        harness = policy_path.resolve().parent.parent / "harness"
        sys.path.insert(0, str(harness))
        from l2_consumer import _minimal_toml  # noqa: PLC0415
        return _minimal_toml(text)


class SolToolGateV2:
    """The governor. One instance per hook invocation (stateless on disk).

    Args:
        root: LOOP root directory.
        policy: parsed policy mapping; loaded fail-closed when ``None``.
        clock: injectable time source.
    """

    def __init__(self, root: Path | str,
                 policy: Mapping[str, Any] | None = None,
                 clock: Any = time.time) -> None:
        self.root = Path(root).resolve()
        self._clock = clock
        self._policy_error: str | None = None
        if policy is None:
            try:
                policy = _load_policy(
                    self.root / "config" / "orchestration_policy_v2.toml")
            except Exception as exc:  # fail closed, remembered for evaluate()
                self._policy_error = "policy unreadable: %s" % exc
                policy = {}
        self.policy = policy
        gov = policy.get("governor", {})
        models = policy.get("models", {})
        budget = policy.get("budget", {})
        self.sol_model = str(models.get("sol_model", "")).strip().lower()
        self.v4_model = str(models.get("v4_model", "")).strip().lower()
        self.k3_model = str(models.get("k3_model", "")).strip().lower()
        self.allowed_states = frozenset(
            gov.get("allowed_states",
                    ["planning", "adjudication", "release_finalize"]))
        self.break_glass_env = str(
            gov.get("break_glass_env", "LOOP_GOVERNOR_OVERRIDE"))
        self.decision_log = self.root / Path(str(
            gov.get("decision_log", "data/governor/gate_decisions.ndjsonl")))
        self.lease_path = self.root / Path(str(
            gov.get("planning_lease_file", "data/governor/planning_lease.json")))
        self.attestations = self.root / Path(str(
            gov.get("attestation_ledger",
                    "data/governor/state_attestations.ndjsonl")))
        self.share_report = self.root / Path(str(
            gov.get("share_report", "data/usage/model_token_share_v2.json")))
        self.stale_after_s = float(
            policy.get("tokens", {}).get("stale_after_s", 7200))
        self.planning_max_turns = int(budget.get("planning_max_turns", 6))
        self.planning_max_new_tokens = int(
            budget.get("planning_max_new_tokens", 30000))
        self.critical_1h_share = float(
            policy.get("hysteresis", {}).get("critical_1h_share", 0.35))

    # -- audit ----------------------------------------------------------------

    def _audit(self, event: str, detail: dict[str, Any]) -> None:
        """Append one audit record; auditing failures degrade to stderr but
        never change the decision (the decision is computed first)."""
        try:
            self.decision_log.parent.mkdir(parents=True, exist_ok=True)
            with open(self.decision_log, "a", encoding="utf-8") as fh:
                fh.write(json.dumps({"ts": self._clock(), "event": event,
                                     **detail}, sort_keys=True) + "\n")
        except OSError as exc:
            sys.stderr.write("sol_tool_gate_v2: audit write failed: %s\n" % exc)

    # -- state derivation -------------------------------------------------------

    def _attested_state(self, explicit: str) -> bool:
        """``True`` iff the newest attestation matches *explicit*.

        Attestations are appended by the harness CLI (``loop_state_set``) —
        a channel the constrained session does not control — as
        ``{"event": "governor.state_set", "state": ..., "reason": ...,
        "idem_key": ...}`` records.
        """
        latest: str | None = None
        try:
            with open(self.attestations, encoding="utf-8") as fh:
                for line in fh:
                    try:
                        obj = json.loads(line)
                    except ValueError:
                        continue
                    if obj.get("event") == "governor.state_set":
                        latest = str(obj.get("state", ""))
        except OSError:
            return False
        return latest == explicit

    def loop_state(self) -> str:
        """Derive the LOOP state; raises on unreadable ledger (fail closed).

        Explicit ``loop_state`` keys are honored only when attested; a bare
        key is ignored and flagged ``governor.state_key_unattested``.
        """
        path = self.root / "data" / "progress_ledger.json"
        led = json.loads(path.read_text(encoding="utf-8"))  # raises → deny
        explicit = led.get("loop_state")
        if isinstance(explicit, str) and explicit:
            if self._attested_state(explicit):
                return explicit
            self._audit("governor.state_key_unattested",
                        {"claimed_state": explicit})
        states = [str(p.get("state")) for p in led.get("packets", {}).values()]
        if not states:
            return "planning"
        if any(s in _ADJUDICATION_STATES for s in states):
            return "adjudication"
        if all(s in _TERMINAL_STATES for s in states):
            return "release_finalize"
        return "execution"  # includes EXPAND_K3 / L2_VERIFY / L2_RANK

    # -- planning lease -----------------------------------------------------------

    def _lease_check(self, new_tokens: int) -> GateDecision | None:
        """Enforce the bounded planning lease; ``None`` = lease healthy.

        The lease counts turns and new tokens since grant; a packet-creation
        event (non-empty ledger) renews it implicitly because the derived
        state stops being "planning".
        """
        now = self._clock()
        lease: dict[str, Any]
        try:
            lease = json.loads(self.lease_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            lease = {"granted_ts": now, "turns_used": 0, "new_tokens_used": 0}
        lease["turns_used"] = int(lease.get("turns_used", 0)) + 1
        lease["new_tokens_used"] = (int(lease.get("new_tokens_used", 0))
                                    + max(0, new_tokens))
        self._write_json(self.lease_path, lease)
        if (lease["turns_used"] > self.planning_max_turns
                or lease["new_tokens_used"] > self.planning_max_new_tokens):
            return GateDecision(
                False,
                "decompose or dispatch: planning lease exhausted (%d turns, "
                "%d new tokens) — emit packets/*.json + dag.json or open an "
                "adjudication packet" % (lease["turns_used"],
                                         lease["new_tokens_used"]),
                state="planning", rule="planning_lease_exhausted")
        return None

    @staticmethod
    def _write_json(path: Path, obj: Any) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=path.name + ".", dir=str(path.parent))
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(obj, fh, sort_keys=True)
            os.replace(tmp, path)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise

    # -- meter integration ---------------------------------------------------------

    def _budget_deny(self, state: str) -> GateDecision | None:
        """Meter v2 actuation: HIGH budget state / critical root ? deny.

        STALE or MISSING reports fail closed for non-planning states — the
        sensor being blind is itself a reason for restraint (§2.4 AC5).
        """
        try:
            report = json.loads(self.share_report.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            report = None
        if report is None or (
                self._clock() - float(report.get("generated_ts", 0))
                > self.stale_after_s):
            if state == "planning":
                return None  # planning turns stay usable while sensors heal
            return GateDecision(
                False,
                "meter report %s — governance sensor blind; fail-closed for "
                "non-planning gated tools. Delegate: dispatch as packet or "
                "open a bounded adjudication packet."
                % ("missing" if report is None else "STALE"),
                state=state, rule="meter_stale_fail_closed")
        if report.get("budget_state") == "HIGH":
            return GateDecision(
                False,
                "Sol 5h effective share %.4f is in HIGH budget state — "
                "delegate: dispatch as packet (dispatch.py --role worker/"
                "verifier) or open a bounded adjudication packet."
                % float(report.get("sol_share_5h_effective") or 0.0),
                state=state, rule="budget_high")
        one_hour = (report.get("windows", {}) or {}).get("rolling_1h", {})
        if one_hour.get("critical_roots"):
            return GateDecision(
                False,
                "a root session exceeds the %.2f 1h critical share "
                "(runaway-root guard) — gated tools denied; delegate."
                % self.critical_1h_share,
                state=state, rule="critical_root_1h")
        return None

    # -- main evaluation --------------------------------------------------------------

    def evaluate(self, payload: Mapping[str, Any]) -> GateDecision:
        """Evaluate one PreToolUse payload. NEVER raises: errors → deny."""
        tool = str(payload.get("tool_name") or "").lower()
        if not tool.startswith(GATED_TOOL_PREFIXES):
            return GateDecision(True, "tool not gated", rule="ungated_tool")

        # Role screen first (upstream v1 semantics): approved child roles are
        # exactly where the work SHOULD run, whatever model they route to.
        role = str(payload.get("agent_type") or payload.get("role")
                   or "").strip().casefold()
        if role in _CHILD_ROLES:
            return GateDecision(True, "approved child role", rule="worker_role")

        model = str(payload.get("model") or "").strip().lower()
        family = None
        if model:
            if model == self.sol_model:
                family = "sol"
            elif model in (self.v4_model, self.k3_model):
                family = "worker"
        if family == "worker":
            # V4/K3 children are exactly where the work SHOULD run.
            return GateDecision(True, "worker-family model", rule="worker_model")
        if family != "sol":
            # Unknown/missing model on a gated tool: a gated operation cannot
            # bypass Sol policy by omitting identity — fail closed.
            return GateDecision(
                False,
                "PreToolUse payload.model is missing or unknown (%r); gated "
                "operations cannot bypass the Sol policy by withholding "
                "identity (fail-closed)" % model,
                rule="unknown_model_fail_closed")

        if self._policy_error:
            return GateDecision(False,
                                "%s — governor cannot read its policy; "
                                "fail-closed" % self._policy_error,
                                rule="policy_unreadable")

        # break-glass: allowed but LOUD — one audit event per bypassed call.
        override = os.environ.get(self.break_glass_env, "").strip()
        if override:
            self._audit("governor.break_glass", {
                "reason": override, "tool": tool})
            return GateDecision(True, "break-glass override: %s" % override,
                                rule="break_glass", break_glass=True)

        try:
            state = self.loop_state()
        except (OSError, ValueError, KeyError) as exc:
            self._audit("governor.fail_closed", {"why": str(exc), "tool": tool})
            return GateDecision(
                False,
                "progress ledger unreadable (%s) — governor fails CLOSED for "
                "gated tools. Packet/dispatch tools remain available: "
                "decompose and dispatch." % exc,
                rule="ledger_unreadable_fail_closed")

        if state == "planning":
            lease_deny = self._lease_check(
                int(payload.get("estimated_new_tokens", 0) or 0))
            if lease_deny is not None:
                return lease_deny

        budget_deny = self._budget_deny(state)
        if budget_deny is not None:
            return budget_deny

        if state in self.allowed_states:
            return GateDecision(True, "state %s allows gated tools" % state,
                                state=state, rule="allowed_state")

        return GateDecision(
            False,
            "LOOP state is %s: this operation belongs to the zero-token "
            "layer or a worker packet (AGENTS.md §2). Dispatch it: "
            "dispatch.py --role worker --packet <id>, or route a "
            "verification-shaped question to the K3 verifier." % state,
            state=state, rule="state_gated")

    def decide(self, payload: Mapping[str, Any]) -> GateDecision:
        """Evaluate + audit one payload (the public entry point)."""
        try:
            decision = self.evaluate(payload)
        except Exception as exc:  # absolute backstop: unknown bug → deny
            decision = GateDecision(
                False, "governor internal error (%s) — fail-closed" % exc,
                rule="internal_error_fail_closed")
        self._audit("governor.decision", {
            "tool": payload.get("tool_name"),
            "allow": decision.allow, "rule": decision.rule,
            "state": decision.state, "reason": decision.reason[:400]})
        return decision


def main(stdin_text: str | None = None) -> int:
    """Hook entry: read the PreToolUse payload, print deny JSON if denied."""
    raw = stdin_text if stdin_text is not None else sys.stdin.read()
    try:
        payload = json.loads(raw) if raw.strip() else {}
    except ValueError:
        payload = {}
    if not payload:
        # No payload at all: nothing identifiable to gate; deny gated-shaped
        # invocations is impossible without a tool name — treat as no-op.
        return 0
    root = os.environ.get("LOOP_ROOT")
    if root is None:
        start = Path(payload.get("cwd") or os.getcwd()).resolve()
        root = str(start)
        for candidate in (start, *start.parents):
            if (candidate / "data" / "progress_ledger.json").exists():
                root = str(candidate)
                break
    gate = SolToolGateV2(root)
    decision = gate.decide(payload)
    output = decision.to_hook_output()
    if output:
        print(output)
    return 0


if __name__ == "__main__":
    logging.basicConfig(level=logging.WARNING)
    sys.exit(main())

#!/usr/bin/env python3
# ============================================================================
# sol_tool_gate.py — PreToolUse gate: mechanical enforcement of Sol discipline
# Purpose : AGENTS.md §2 says Sol rounds are only for planning/adjudication —
#           but prose cannot enforce itself (P1-1). This hook makes it
#           mechanical: when the LOOP state is NOT planning / adjudication /
#           release_finalize and the ROOT (Sol) session tries to run shell,
#           search, bulk file reads, tests, or statistics, the tool call is
#           DENIED with an instruction to dispatch the work as an L0/L1
#           packet instead. Explicit approved child roles are never gated (they
#           are the dispatch targets); spawn gates separately prevent Sol
#           children and recursive births. Gate errors fail OPEN with a note: an
#           unreadable ledger must never paralyze the session (observation
#           of the failure is the fail-visible part).
# Input   : PreToolUse hook payload (one JSON object on stdin; fields used:
#           tool_name, agent_type/agent_id if present, cwd), env LOOP_ROOT
#           (default: cwd), data/progress_ledger.json (current LOOP state:
#           explicit "loop_state" key wins, else derived from packet states).
# Output  : deny -> {"hookSpecificOutput":{"hookEventName":"PreToolUse",
#           "permissionDecision":"deny","permissionDecisionReason":...}} on
#           stdout, exit 0; allow -> no output, exit 0.
# Lines   : ~80 (excluding this header)
# ============================================================================
import json
import os
import sys
import time
from pathlib import Path

# Planning-stage parallel-recon enforcement: root may serially read this many
# times before the gate starts denying with a spawn order (throughput-first
# delegation, AGENTS.md).  A successful spawn resets the counter; after
# RECON_HARD_CAP consecutive denies the gate fails open (never paralyze root).
RECON_THRESHOLD = 5
RECON_HARD_CAP = 8
RECON_WINDOW = 900

# Sol may use any tool in these LOOP states (planning decomposition,
# adjudication evidence reads, release finalize checks).
ALLOWED_STATES = {"planning", "adjudication", "release_finalize"}

# Tool names (lowercased, prefix-matched) that constitute L0 data processing
# when issued from the root Sol session mid-execution.
GATED_TOOLS = ("shell", "shell_command", "bash", "local_shell", "exec_command",
               "functions.exec", "run_terminal", "terminal", "web_search",
               "search", "grep", "glob", "mcp__", "read_mcp_resource",
               "list_mcp", "read_many_files", "read_file", "list_files",
               "pytest", "test")

ADJUDICATION_STATES = {"SOL_ADJUDICATE", "DEAD_LETTER", "MERGE_CONFLICT",
                       "WAVE_DONE", "WAVE_DONE_READY", "SOL_WAKE"}
TERMINAL_STATES = {"MERGED", "DONE"}
CHILD_ROLES = {"worker", "verifier", "reviewer", "plan_expander",
               "duty_officer", "explorer"}


def loop_state(root):
    """Current LOOP state: explicit ledger key wins, else derived from packet
    states. No packets = planning; any adjudication-class packet = adjudication;
    all terminal = release_finalize; anything else = execution."""
    path = os.path.join(root, "data", "progress_ledger.json")
    led = json.load(open(path, encoding="utf-8"))
    explicit = led.get("loop_state")
    if isinstance(explicit, str) and explicit:
        return explicit
    states = [p.get("state") for p in led.get("packets", {}).values()]
    if not states:
        return "planning"
    if any(s in ADJUDICATION_STATES for s in states):
        return "adjudication"
    if all(s in TERMINAL_STATES for s in states):
        return "release_finalize"
    return "execution"


def loop_root(payload):
    explicit = os.environ.get("LOOP_ROOT")
    if explicit:
        return explicit
    start = Path(payload.get("cwd") or os.getcwd()).resolve()
    for candidate in (start, *start.parents):
        if (candidate / "data" / "progress_ledger.json").exists():
            return str(candidate)
    here = Path(__file__).resolve()
    installed = (here.parents[2] if here.parent.name == "hooks"
                 and here.parent.parent.name == ".codex" else here.parents[1])
    return str(installed)


def recon_enforce(root, tool):
    """PLANNING parallel-recon enforcement.  Serial root reads past
    RECON_THRESHOLD are denied with an explicit spawn order; a spawn resets
    the counter; RECON_HARD_CAP consecutive denies fail open."""
    if "spawn" in tool or "subagent" in tool or "dispatch" in tool:
        f = _recon_file(root)
        if f.exists():
            f.unlink()
        return ""
    now = time.time()
    f = _recon_file(root)
    try:
        st = json.loads(f.read_text(encoding="utf-8"))
    except Exception:
        st = {}
    if now - float(st.get("window", 0)) > RECON_WINDOW:
        st = {}
    count = int(st.get("count", 0)) + 1
    st.update({"count": count, "window": st.get("window") or now, "last_tool": tool})
    f.parent.mkdir(parents=True, exist_ok=True)
    f.write_text(json.dumps(st), encoding="utf-8")
    if count > RECON_HARD_CAP:
        return ""
    if count >= RECON_THRESHOLD:
        pin_model, pin_effort = _pinned_worker_route(root)
        if pin_model:
            pin_line = ('"model": "%s", "reasoning_effort": "%s", '
                        % (pin_model, pin_effort))
            pin_note = ("model 字段必须逐字带上（来自当前激活 profile），"
                        "禁止省略——省略会被路由到错误的模型：")
        else:
            pin_line = '"model": "<读取 config/model_profiles.toml active_profile 的 execution_model>", '
            pin_note = ("model 字段必须来自当前激活 profile（本机无法读取时按占位符"
                        "提示查询），禁止省略——省略会被路由到错误的模型：")
        tpl = (
            "PLANNING 强制委派：root 已连续串行读取 %d 次（本窗口）。"
            "spawn 工具是延迟加载的：若本会话工具列表里没有 multi_agent_v1.spawn_agent，"
            "必须先调用 tool_search 工具（参数 {\"query\": \"spawn agent\"}）激活它，"
            "它会在你的下一轮出现，然后再 spawn。"
            "照抄此模板，一轮内并列发出 ≥4 个调用（每个 message 不同分片，只读侦查，禁止写）。"
            + pin_note +
            '{"agent_type": "worker", "fork_context": false, '
            + pin_line +
            '"message": "任务名：侦查harness目录结构\\n只读侦查 <具体路径/检索目标>，'
            '输出<你要的结论格式>。禁止修改任何文件。"}  '
            "4 个并行分片建议：目录结构与文件清单 / 核心模块符号表(rg) / 测试面与验收命令 / "
            "git 状态与历史 evidence。spawn 成功后本 gate 自动放行；"
            "继续发串行读取会被继续拒绝。" % count)
        return tpl
    return ""


def _pinned_worker_route(root):
    """Execution route from the ACTIVE profile (config/model_profiles.toml) —
    the same source root_agent_spawn_gate.approved_route enforces.  The deny
    template must never hardcode a model string: on the next profile rotation
    a baked-in pin would instruct a model the spawn gate then DENIES."""
    try:
        import tomllib
        doc = tomllib.loads((Path(root) / "config" / "model_profiles.toml")
                            .read_text(encoding="utf-8"))
        profile = (doc.get("profiles") or {}).get(doc.get("active_profile")) or {}
        model = profile.get("execution_model")
        effort = profile.get("execution_reasoning")
        if (isinstance(model, str) and "/" in model
                and isinstance(effort, str) and effort.strip()):
            return model.strip(), effort.strip()
    except Exception:
        pass
    return None, None


def _recon_file(root):
    return Path(root) / "data" / "governor" / "recon_gate.json"


def main():
    try:
        payload = json.load(sys.stdin)
    except (json.JSONDecodeError, ValueError):
        return 0  # fail-open: no payload, nothing to judge
    # Subagents are never gated — they are exactly where the work SHOULD run.
    tool = (payload.get("tool_name") or "").lower()
    if "spawn" in tool or "subagent" in tool or "dispatch" in tool:
        # a spawn IS the forced delegation: reset the recon counter
        try:
            rf = _recon_file(loop_root(payload))
            if rf.exists():
                rf.unlink()
        except OSError:
            pass
        return 0
    if not tool.startswith(GATED_TOOLS):
        return 0
    role = str(payload.get("agent_type") or payload.get("role") or "").strip().casefold()
    if role in CHILD_ROLES:
        return 0
    if role and role not in ("sol", "root", "default"):
        print(json.dumps({"hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason":
                "PreToolUse payload.agent_type is unknown (%r); an unknown "
                "role cannot bypass the Sol policy" % role}}))
        return 0
    root = loop_root(payload)
    try:
        state = loop_state(root)
    except (OSError, ValueError, json.JSONDecodeError) as e:
        sys.stderr.write("sol_tool_gate: ledger unreadable (%s) — failing open\n" % e)
        return 0
    if state in ALLOWED_STATES:
        if state == "planning":
            reason = recon_enforce(root, tool)
            if reason:
                print(json.dumps({"hookSpecificOutput": {
                    "hookEventName": "PreToolUse",
                    "permissionDecision": "deny",
                    "permissionDecisionReason": reason}}))
        return 0
    print(json.dumps({"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason":
            "LOOP state is %s, this operation should be dispatched to an "
            "L0/L1 packet (AGENTS.md §2: Sol rounds are for planning/"
            "adjudication only — shell/search/bulk-read/test/statistics "
            "belong to the zero-token layer or a worker packet)" % state}}))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Fail-open lifecycle hook for Desktop-native Codex subagents.

This hook maintains a shadow roster and a semantic task-name map.  It never
writes Codex Desktop's ``state_5.sqlite`` and never claims to release a native
runtime slot: the host-only ``close_agent`` tool is represented by an
idempotent close-request record for the orchestrator to consume.
"""
from __future__ import annotations

import argparse
import contextlib
import ctypes
import json
import os
import re
import subprocess
import sys
import time
from pathlib import Path
from typing import Any

if os.name == "nt":
    from ctypes import wintypes


TASK_RE = re.compile(r"(?:^|\n)\s*任务名\s*[：:]\s*([^\r\n]{1,160})")
ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]{0,127}\Z")
PENDING_TTL_SECONDS = 600
# Terminal lifecycle records are audit-redundant (events.ndjson, name_map.jsonl
# and exec history keep the evidence). Without pruning, exec_roster.json and
# native_roster.json grow unbounded and slow every roster reader.
ROSTER_PRUNE_AFTER_S = 48 * 3600
TERMINAL_MARKERS = {"task_complete", "turn_aborted", "turn_failed", "thread_closed"}
LEGACY_UNRESOLVED_NAMES = {"未命名子任务", "未映射子任务"}
NAME_FALLBACK_SOURCE = "agent_id_fallback"
ATOMIC_REPLACE_TIMEOUT_S = 5.0
RETRY_INITIAL_S = 0.005
RETRY_MAX_S = 0.100
LOCK_TIMEOUT_S = 10.0
def _tool_arguments(payload: dict[str, Any]) -> dict[str, Any]:
    value = payload.get("tool_input") or payload.get("input") or payload.get("arguments") or {}
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            value = {}
    return value if isinstance(value, dict) else {}


def _spawn_prompt(arguments: dict[str, Any]) -> str:
    if isinstance(arguments.get("message"), str):
        return arguments["message"]
    items = arguments.get("items")
    if isinstance(items, list):
        return "\n".join(str(item.get("text") or "") for item in items
                         if isinstance(item, dict) and item.get("type") == "text")
    return ""


def project_root() -> Path:
    explicit = os.environ.get("LOOP_ROOT")
    if explicit:
        return Path(explicit).resolve()
    here = Path(__file__).resolve()
    # package/hooks/script.py or target/.codex/hooks/script.py
    return here.parents[2] if here.parent.name == "hooks" and here.parent.parent.name == ".codex" else here.parents[1]


def data_dir() -> Path:
    return Path(os.environ.get("LOOP_DATA_DIR", str(project_root() / "data"))).resolve()


def recompute_refill(root: Path | None = None) -> dict[str, Any] | None:
    """Mechanically recompute the sustained-refill state after a lifecycle event.

    The hook never spawns: it imports the refill controller (harness/) and asks
    it to re-derive refill_required / deficit / model_pool from the native
    roster and the work queue.  Failures are audited and never faked as
    refilled.
    """
    base = (root or project_root()).resolve()
    pkg_harness = Path(__file__).resolve().parents[1] / "harness"
    try:
        for candidate in (pkg_harness, base / "harness"):
            if (candidate / "refill_controller_v2.py").exists():
                sys.path.insert(0, str(candidate))
                break
        from orchestration_common import LoopPaths
        from refill_controller_v2 import RefillControllerV2
        controller = RefillControllerV2(LoopPaths.resolve(base))
        controller.queue_sync_ledger()
        return controller.recompute()
    except BaseException as exc:
        try:
            NativeRoster(data_dir()).audit("refill_recompute_degraded",
                                           error="%s: %s" % (type(exc).__name__, exc))
        except BaseException:
            pass
        return None


def schedule_refill_actuator(root: Path | None = None, *, source: str) -> dict[str, Any] | None:
    """Trigger the existing epilogue after a terminal lifecycle edge.

    ``recompute_refill`` is the controller (observe + decide), not the
    actuator.  Desktop-native terminal hooks previously stopped after that
    decision, so a real deficit stayed queued until the root agent manually
    dispatched again.  Reuse the headless supervisor's coalesced epilogue
    launcher; it owns the existing epilogue lock and the packet-only refill
    consumer.  This remains fail-open for the lifecycle hook: a failed trigger
    is audited and never reported as a successful refill.
    """
    base = (root or project_root()).resolve()
    try:
        harness = Path(__file__).resolve().parents[1] / "harness"
        if str(harness) not in sys.path:
            sys.path.insert(0, str(harness))
        from refill_consumer_v2 import schedule_run
        result = schedule_run(base, source=source)
        try:
            NativeRoster(data_dir()).audit("refill_actuator_%s" % result.get("status", "unknown"),
                                           source=source, pid=result.get("pid"))
        except BaseException:
            pass
        return result
    except BaseException as exc:
        try:
            NativeRoster(data_dir()).audit("refill_actuator_failed", source=source,
                                           error="%s: %s" % (type(exc).__name__, exc))
        except BaseException:
            pass
        return None


def refresh_meter(root: Path | None = None) -> dict[str, Any] | None:
    """Trigger the meter bridge WITHOUT blocking the hook (P0 2026-08-30).

    The bridge parses every rollout modified in its window; on a heavily used
    machine that scan takes 30s+ once the debounce expires, which used to run
    INLINE on SessionStart/Stop and became the conversation's first-token
    latency (the hook was killed at its 30s timeout).  The bridge owns its
    cross-process lock and debounce, so firing it detached converges safely
    and the hook returns immediately.
    """
    base = (root or project_root()).resolve()
    try:
        bridge = base / "metering" / "model_token_share_bridge.py"
        if not bridge.exists():
            return None
        sessions = Path(os.environ.get(
            "CODEX_SESSIONS_DIR",
            str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
        )).resolve()
        creationflags = 0
        if os.name == "nt":
            creationflags = 0x00000008 | 0x00000200  # DETACHED_PROCESS | NEW_PROCESS_GROUP
        subprocess.Popen(
            [sys.executable, str(bridge), "--root", str(base),
             "--sessions-dir", str(sessions)],
            stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL, creationflags=creationflags,
            close_fds=True)
        return {"status": "detached"}
    except BaseException as exc:
        try:
            NativeRoster(data_dir()).audit("meter_refresh_degraded",
                                           error="%s: %s" % (type(exc).__name__, exc))
        except BaseException:
            pass
        return None


@contextlib.contextmanager
def lock(path: Path, *, timeout_s: float = LOCK_TIMEOUT_S):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a+b") as handle:
        handle.seek(0, os.SEEK_END)
        if handle.tell() == 0:
            handle.write(b"\0"); handle.flush()
        handle.seek(0)
        if os.name == "nt":
            import msvcrt
            deadline = time.monotonic() + max(0.0, timeout_s)
            backoff = RETRY_INITIAL_S
            while True:
                try:
                    msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                    break
                except OSError as exc:
                    if time.monotonic() >= deadline:
                        raise RuntimeError(
                            "lifecycle hook lock remained busy for %.3fs: %s"
                            % (timeout_s, exc)) from exc
                    time.sleep(backoff)
                    backoff = min(RETRY_MAX_S, backoff * 2)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def atomic_json(path: Path, value: Any, *,
                replace_timeout_s: float = ATOMIC_REPLACE_TIMEOUT_S) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".%d.tmp" % os.getpid())
    try:
        with tmp.open("w", encoding="utf-8", newline="\n") as handle:
            json.dump(value, handle, ensure_ascii=False, indent=2, sort_keys=True)
            handle.write("\n"); handle.flush(); os.fsync(handle.fileno())
        deadline = time.monotonic() + max(0.0, replace_timeout_s)
        backoff = RETRY_INITIAL_S
        while True:
            try:
                os.replace(tmp, path)
                return
            except PermissionError as exc:
                if time.monotonic() >= deadline:
                    raise RuntimeError(
                        "lifecycle hook atomic replace remained blocked for "
                        "%.3fs: %s" % (replace_timeout_s, exc)) from exc
                time.sleep(backoff)
                backoff = min(RETRY_MAX_S, backoff * 2)
    finally:
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass


def read_json(path: Path, default: Any) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


class NativeRoster:
    def __init__(self, root: Path):
        self.root = root / "lifecycle"
        self.path = self.root / "native_roster.json"
        self.lock_path = self.root / ".native_roster.lock"
        self.close_path = self.root / "close_requests.ndjson"
        self.events_path = self.root / "events.ndjson"
        self.name_map_path = self.root / "name_map.jsonl"
        self.main_events_path = root / "events.ndjson"

    def transact(self, fn):
        with lock(self.lock_path):
            if self.path.exists():
                try:
                    roster = json.loads(self.path.read_text(encoding="utf-8"))
                except (OSError, ValueError) as exc:
                    raise RuntimeError("native roster unreadable; refusing overwrite: %s" % exc) from exc
            else:
                roster = {"schema": "codex-loop-native-roster/v1",
                          "pending": [], "agents": {}}
            result = fn(roster)
            roster["updated_at"] = time.time()
            atomic_json(self.path, roster)
            return result

    def append(self, path: Path, row: dict[str, Any]) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("a", encoding="utf-8", newline="\n") as handle:
            handle.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")

    def audit(self, event: str, **detail: Any) -> None:
        with lock(self.lock_path.with_name(".native_events.lock")):
            self.append(self.events_path, {"ts": time.time(), "event": event, **detail})

    def main_event_once(self, event: str, agent_id: str, **detail: Any) -> bool:
        with lock(self.lock_path.with_name(".events.lock")):
            try:
                for line in self.main_events_path.read_text(encoding="utf-8").splitlines():
                    try: row = json.loads(line)
                    except ValueError: continue
                    if row.get("event") == event and row.get("agent_id") == agent_id:
                        return False
            except OSError:
                pass
            self.append(self.main_events_path, {"ts": time.time(), "event": event,
                                                "agent_id": agent_id, **detail})
            return True

    def exec_event_once(self, packet_id: str, run_id: str, attempt: int,
                        event: str, **detail: Any) -> bool:
        with lock(self.lock_path.with_name(".events.lock")):
            try:
                for line in self.main_events_path.read_text(encoding="utf-8").splitlines():
                    try: row = json.loads(line)
                    except ValueError: continue
                    if (row.get("packet_id") == packet_id and row.get("run_id") == run_id
                            and row.get("event") == event):
                        return False
            except OSError:
                pass
            self.append(self.main_events_path, {"ts": time.time(), "packet_id": packet_id,
                "run_id": run_id, "attempt": attempt, "event": event, "detail": detail})
            return True

    def queue_close_locked(self, agent: dict[str, Any], reason: str) -> bool:
        if agent.get("close_request_emitted") or agent.get("close_request_consumed"):
            return False
        agent_id = agent.get("agent_id")
        # The append-only close_requests ledger is the durable exactly-once
        # truth: a roster rebuild (e.g. after a corrupt native_roster.json)
        # resets the in-memory flag and would double-emit a close request.
        try:
            if self.close_path.exists():
                for line in self.close_path.read_text(encoding="utf-8").splitlines():
                    if not line.strip():
                        continue
                    try:
                        row = json.loads(line)
                    except ValueError:
                        continue
                    if row.get("agent_id") == agent_id and row.get("action") == "host_close_agent_required":
                        agent["close_request_emitted"] = True
                        return False
        except OSError:
            pass  # unreadable ledger: fall through to the flag-based guard
        row = {"ts": time.time(), "agent_id": agent_id,
               "task_name": agent.get("task_name"), "parent_session_id": agent.get("parent_session_id"),
               "reason": reason, "action": "host_close_agent_required"}
        self.append(self.close_path, row)
        agent["close_request_emitted"] = True
        agent["close_request_reason"] = reason
        return True


def payload_task_name(payload: dict[str, Any]) -> str | None:
    tool_input = payload.get("tool_input") or payload.get("input") or payload.get("arguments") or {}
    if isinstance(tool_input, str):
        try: tool_input = json.loads(tool_input)
        except ValueError: tool_input = {"message": tool_input}
    if not isinstance(tool_input, dict):
        tool_input = {}
    explicit = tool_input.get("task_name") or tool_input.get("name")
    if isinstance(explicit, str) and explicit.strip():
        return explicit.strip()[:160]
    # Current multi-agent payloads may normalize the legacy ``message`` into
    # structured ``items``. Walk only in-memory strings and persist only the
    # matched one-line task name, never the raw tool payload.
    queue: list[Any] = [tool_input]
    while queue:
        value = queue.pop()
        if isinstance(value, str):
            match = TASK_RE.search(value)
            if match:
                return match.group(1).strip()[:160]
        elif isinstance(value, dict):
            queue.extend(value.values())
        elif isinstance(value, list):
            queue.extend(value)
    return None


def tool_is_spawn_agent(tool: Any) -> bool:
    value = str(tool or "").casefold()
    if "spawn_agent" in value:
        return True
    folded = "".join(ch for ch in value if ch.isalnum())
    return folded in {"agent", "spawnagent"} or "spawnagent" in folded


def resolve_identity(payload: dict[str, Any], roster: NativeRoster,
                     context: str) -> tuple[str | None, str | None] | None:
    """Resolve identity fields, auditing and blocking on conflicting duplicates."""
    agent_id = payload.get("agent_id")
    thread_id = payload.get("thread_id")
    session_id = payload.get("session_id")
    parent_thread_id = payload.get("parent_thread_id")
    raw_id = payload.get("id")
    if agent_id and thread_id and str(agent_id) != str(thread_id):
        roster.audit("identity_conflict", context=context, pair="agent_id/thread_id",
                     agent_id=str(agent_id), thread_id=str(thread_id), action="fail_closed")
        return None
    if session_id and parent_thread_id and str(session_id) != str(parent_thread_id):
        roster.audit("identity_conflict", context=context, pair="session_id/parent_thread_id",
                     session_id=str(session_id), parent_thread_id=str(parent_thread_id),
                     action="fail_closed")
        return None
    parent = session_id or parent_thread_id
    agent = agent_id or thread_id
    parent_s = str(parent) if parent else ""
    raw_s = str(raw_id) if raw_id else ""
    # Official SubagentStart uses session_id=parent and may put the child in
    # ``id`` instead of agent_id. ``id`` equal to the parent is the session, not
    # the child, so it must not become agent_id.
    if agent and raw_id and raw_s not in {"", parent_s} and str(agent) != raw_s:
        roster.audit("identity_conflict", context=context, pair="agent_id/id",
                     agent_id=str(agent), id=raw_s, action="fail_closed")
        return None
    if not agent and raw_id and raw_s and raw_s != parent_s:
        agent = raw_id
    return agent, parent


def recover_arguments_from_parent_rollout(parent_session_id: str | None,
                                          tool_use_id: str | None,
                                          sessions: Path | None = None) -> dict[str, Any] | None:
    """Recover tool arguments when PreToolUse redacts collaboration input.

    Current Desktop builds expose the tool-use id to the hook but can omit the
    spawn message. The parent rollout is the second truth source and already
    contains the function_call before SubagentStart fires.
    """
    if (not parent_session_id or not tool_use_id or
            not ID_RE.fullmatch(str(parent_session_id)) or
            not ID_RE.fullmatch(str(tool_use_id))):
        return None
    root = sessions or Path(os.environ.get("CODEX_SESSIONS_DIR", str(Path.home() / ".codex" / "sessions")))
    if not root.exists():
        return None
    matches = list(root.rglob("rollout-*%s*.jsonl" % parent_session_id))
    for path in sorted(matches, key=lambda p: p.stat().st_mtime, reverse=True):
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    try: row = json.loads(line)
                    except ValueError: continue
                    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                    if payload.get("type") != "function_call" or payload.get("call_id") != tool_use_id:
                        continue
                    arguments = payload.get("arguments") or {}
                    if isinstance(arguments, str):
                        try: arguments = json.loads(arguments)
                        except ValueError: arguments = {"message": arguments}
                    return arguments if isinstance(arguments, dict) else None
        except OSError:
            continue
    return None


def recover_spawn_agent_id(parent_session_id: str | None, tool_use_id: str | None,
                           sessions: Path | None = None) -> str | None:
    """Resolve spawn call_id -> returned agent_id from the parent rollout."""
    if (not parent_session_id or not tool_use_id or
            not ID_RE.fullmatch(str(parent_session_id)) or
            not ID_RE.fullmatch(str(tool_use_id))):
        return None
    root = sessions or Path(os.environ.get("CODEX_SESSIONS_DIR", str(Path.home() / ".codex" / "sessions")))
    if not root.exists():
        return None
    for path in sorted(root.rglob("rollout-*%s*.jsonl" % parent_session_id),
                       key=lambda p: p.stat().st_mtime, reverse=True):
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    if tool_use_id not in line or "function_call_output" not in line:
                        continue
                    try: row = json.loads(line)
                    except ValueError: continue
                    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                    if payload.get("type") != "function_call_output" or payload.get("call_id") != tool_use_id:
                        continue
                    output = payload.get("output") or {}
                    if isinstance(output, str):
                        try: output = json.loads(output)
                        except ValueError: continue
                    candidate = output.get("agent_id") if isinstance(output, dict) else None
                    return str(candidate) if candidate and ID_RE.fullmatch(str(candidate)) else None
        except OSError:
            continue
    return None


def recover_task_from_parent_rollout(parent_session_id: str | None,
                                     tool_use_id: str | None,
                                     sessions: Path | None = None) -> str | None:
    arguments = recover_arguments_from_parent_rollout(parent_session_id, tool_use_id, sessions)
    return payload_task_name({"tool_input": arguments or {}})


def pre_tool(roster: NativeRoster, payload: dict[str, Any]) -> None:
    tool = str(payload.get("tool_name") or payload.get("tool") or payload.get("name") or "")
    resolved = resolve_identity(payload, roster, "PreToolUse")
    if resolved is None:
        return
    parent = resolved[1]
    tool_use_id = payload.get("tool_use_id")
    if "close_agent" in tool:
        tool_input = payload.get("tool_input") or payload.get("input") or payload.get("arguments") or {}
        if isinstance(tool_input, str):
            try: tool_input = json.loads(tool_input)
            except ValueError: tool_input = {}
        if not isinstance(tool_input, dict): tool_input = {}
        target = tool_input.get("target") or tool_input.get("agent_id") or tool_input.get("id")
        if not target:
            recovered = recover_arguments_from_parent_rollout(parent, tool_use_id)
            if recovered:
                target = recovered.get("target") or recovered.get("agent_id") or recovered.get("id")
        if target:
            def confirm(value):
                item = value.setdefault("agents", {}).get(str(target))
                if not item: return None
                if not item.get("host_close_confirmed_at"):
                    item["host_close_confirmed_at"] = time.time()
                    item["close_request_consumed"] = True
                    item["close_observed_before_request"] = not bool(item.get("close_request_emitted"))
                    item["updated_at"] = time.time()
                return dict(item)
            item = roster.transact(confirm)
            if item:
                roster.audit("host_close_observed", agent_id=str(target),
                             task_name=item.get("task_name"), tool_use_id=tool_use_id)
                recompute_refill()
                schedule_refill_actuator(project_root(), source="desktop_close_observed")
        return
    if not tool_is_spawn_agent(tool):
        return
    arguments = _tool_arguments(payload)
    prompt = _spawn_prompt(arguments)
    task_name = payload_task_name(payload)
    item = {"task_name": task_name, "parent_session_id": parent,
            "tool_use_id": tool_use_id, "created_at": time.time(),
            "status": "pending_start",
            "model": arguments.get("model")}
    def mutate(value):
        expired = prune_pending(value, item["created_at"])
        pending = value.setdefault("pending", [])
        key = (item["parent_session_id"], item["tool_use_id"])
        if item["tool_use_id"] and any((x.get("parent_session_id"), x.get("tool_use_id")) == key for x in pending):
            return False, expired
        pending.append(item); return True, expired
    added, expired = roster.transact(mutate)
    if expired:
        roster.audit("pending_expired", count=len(expired),
                     tool_use_ids=[x.get("tool_use_id") for x in expired],
                     trigger="PreToolUse")
    if added:
        roster.audit("spawn_pending", **item)


def prune_pending(value: dict[str, Any], now: float) -> list[dict[str, Any]]:
    """Drop expired or malformed pending starts before matching/de-duplication."""
    active, expired = [], []
    for item in value.setdefault("pending", []):
        if item.get("status") != "pending_start":
            continue
        try:
            created_at = float(item.get("created_at", 0) or 0)
        except (TypeError, ValueError):
            created_at = 0.0
        if now - created_at > PENDING_TTL_SECONDS:
            expired.append(item)
        else:
            active.append(item)
    value["pending"] = active
    return expired


def subagent_start(roster: NativeRoster, payload: dict[str, Any]) -> None:
    resolved = resolve_identity(payload, roster, "SubagentStart")
    if resolved is None:
        return
    agent_id, parent = resolved
    if not agent_id:
        roster.audit("subagent_start_degraded", reason="missing_agent_id")
        return
    now = time.time()
    def mutate(value):
        agents = value.setdefault("agents", {})
        if agent_id in agents:
            return agents[agent_id], []
        expired = prune_pending(value, now)
        pending = value.setdefault("pending", [])
        candidates = [x for x in pending
                      if x.get("status") == "pending_start" and
                      (not parent or not x.get("parent_session_id") or x.get("parent_session_id") == parent)]
        exact = [x for x in candidates
                 if recover_spawn_agent_id(parent, x.get("tool_use_id")) == str(agent_id)]
        chosen = min(exact, key=lambda x: x.get("created_at", 0)) if exact else (
                 candidates[0] if len(candidates) == 1 else None)
        if chosen:
            pending.remove(chosen)
            if chosen in exact:
                chosen["mapping_source"] = "parent_rollout_function_call_output"
        task_name = chosen.get("task_name") if chosen else None
        if task_name in LEGACY_UNRESOLVED_NAMES:
            task_name = None
        if chosen and task_name is None:
            recovered = recover_task_from_parent_rollout(parent, chosen.get("tool_use_id"))
            if recovered:
                task_name = recovered
                chosen["task_name"] = recovered
                chosen["mapping_source"] = "parent_rollout_function_call"
        name_degraded = False
        name_source = None
        if not task_name:
            task_name = str(agent_id)
            name_degraded = True
            name_source = NAME_FALLBACK_SOURCE
        item = {"agent_id": agent_id, "task_name": task_name,
                 "name_degraded": name_degraded, "name_source": name_source,
                 "parent_session_id": parent, "agent_role": payload.get("agent_type") or payload.get("agent_role"),
                 "model": payload.get("model") or payload.get("agent_model") or
                           (chosen or {}).get("model"),
                "nickname": payload.get("agent_nickname"), "status": "running",
                "started_at": now, "updated_at": now,
                "mapping_confidence": ("tool_use+rollout" if chosen and chosen.get("mapping_source") else
                                       "tool_use" if chosen and chosen.get("tool_use_id") else
                                       "parent_fifo" if chosen else "unmapped")}
        agents[agent_id] = item
        self_row = {**item, "source": "SubagentStart"}
        roster.append(roster.name_map_path, self_row)
        return item, expired
    item, expired = roster.transact(mutate)
    if expired:
        roster.audit("pending_expired", count=len(expired),
                     tool_use_ids=[x.get("tool_use_id") for x in expired])
    roster.main_event_once("SubagentStart", str(agent_id),
                           agent_role=item.get("agent_role"), model=item.get("model"),
                           session_id=item.get("parent_session_id"), task_name=item.get("task_name"))
    roster.audit("subagent_started", **item)


def subagent_stop(roster: NativeRoster, payload: dict[str, Any]) -> None:
    resolved = resolve_identity(payload, roster, "SubagentStop")
    if resolved is None:
        return
    agent_id, _parent = resolved
    if not agent_id:
        roster.audit("subagent_stop_degraded", reason="missing_agent_id")
        return
    now = time.time()
    def mutate(value):
        item = value.setdefault("agents", {}).setdefault(agent_id,
            {"agent_id": agent_id, "task_name": str(agent_id), "started_at": None,
             "name_degraded": True, "name_source": NAME_FALLBACK_SOURCE})
        item.update(status="terminal", terminal_reason="SubagentStop",
                    stopped_at=now, updated_at=now)
        queued = roster.queue_close_locked(item, "subagent_terminal")
        return dict(item), queued
    item, queued = roster.transact(mutate)
    roster.main_event_once("SubagentStop", str(agent_id),
                           session_id=item.get("parent_session_id"),
                           task_name=item.get("task_name"))
    roster.audit("subagent_stopped", agent_id=agent_id, task_name=item.get("task_name"), close_queued=queued)
    recompute_refill()
    schedule_refill_actuator(project_root(), source="desktop_subagent_stop")


def parent_stop(roster: NativeRoster, payload: dict[str, Any]) -> None:
    resolved = resolve_identity(payload, roster, "Stop")
    if resolved is None:
        return
    _agent, parent = resolved
    if not parent:
        roster.audit("parent_stop_degraded", reason="missing_session_id",
                     native_agents=[], exec_packets=[])
        return
    parent = str(parent)
    parent_state_path = data_dir() / "refill" / "parent_sessions.json"
    with lock(data_dir() / "refill" / ".parent_sessions.lock"):
        parent_states = read_json(parent_state_path, {"parents": {}})
        item = parent_states.setdefault("parents", {}).setdefault(str(parent), {})
        item.update(active=False, stopped_at=time.time(), source="parent_stop")
        atomic_json(parent_state_path, parent_states)
    now = time.time()
    def mutate(value):
        changed = []
        for item in value.setdefault("agents", {}).values():
            if item.get("status") == "running" and item.get("parent_session_id") == parent:
                item.update(status="interrupted", terminal_reason="parent_stop", stopped_at=now, updated_at=now)
                roster.queue_close_locked(item, "parent_stop")
                changed.append(item.get("agent_id"))
        return changed
    changed = roster.transact(mutate)

    # Request cancellation for all live codex-exec jobs.  Their supervisors
    # own the strong OS handles and perform the actual process-tree shutdown.
    with lock(roster.root / ".exec_roster.lock"):
        exec_roster = read_json(roster.root / "exec_roster.json", {"jobs": {}})
    cancel_dir = roster.root / "cancel"; cancel_dir.mkdir(parents=True, exist_ok=True)
    exec_cancelled = []
    for packet_id, item in exec_roster.get("jobs", {}).items():
        if (item.get("state") in ("starting", "running") and
                item.get("parent_session_id") == parent and item.get("run_id") is not None):
            atomic_json(cancel_dir / (packet_id + ".json"),
                        {"ts": now, "reason": "parent_stop", "parent_session_id": parent,
                         "run_id": item.get("run_id"), "attempt": item.get("attempt", 0)})
            exec_cancelled.append(packet_id)
    roster.audit("parent_stop", parent_session_id=parent, native_agents=changed, exec_packets=exec_cancelled)
    recompute_refill(project_root())
    schedule_refill_actuator(project_root(), source="desktop_parent_stop")


def rollout_info(path: Path) -> tuple[dict[str, Any], str | None]:
    meta: dict[str, Any] = {}
    terminal = None
    try:
        with path.open(encoding="utf-8", errors="replace") as handle:
            for line in handle:
                try: row = json.loads(line)
                except ValueError: continue
                kind = row.get("type")
                payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                if kind == "session_meta":
                    source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
                    spawn = source.get("subagent", {}).get("thread_spawn", {}) if isinstance(source.get("subagent"), dict) else {}
                    meta = {"nickname": payload.get("agent_nickname") or spawn.get("agent_nickname"),
                            "agent_role": payload.get("agent_role") or spawn.get("agent_role"),
                            "agent_path": payload.get("agent_path") or spawn.get("agent_path"),
                            "rollout_path": str(path)}
                candidates = {kind, payload.get("type"), payload.get("event")}
                hit = next((x for x in candidates if x in TERMINAL_MARKERS), None)
                if hit: terminal = str(hit)
    except OSError:
        pass
    return meta, terminal


def cold_reconcile(roster: NativeRoster, sessions: Path) -> None:
    def snapshot(value):
        return [(aid, dict(item)) for aid, item in value.setdefault("agents", {}).items()
                if item.get("status") in ("running", "interrupted")]
    active = roster.transact(snapshot)
    found = 0
    for agent_id, old in active:
        matches = list(sessions.rglob("rollout-*%s*.jsonl" % agent_id)) if sessions.exists() else []
        if not matches: continue
        path = max(matches, key=lambda p: p.stat().st_mtime)
        meta, terminal = rollout_info(path)
        def mutate(value, aid=agent_id, info=meta, term=terminal):
            item = value.setdefault("agents", {}).get(aid)
            if not item: return False
            for key, val in info.items():
                if val: item[key] = val
            if term:
                item.update(status="terminal", terminal_reason="rollout_%s" % term,
                            stopped_at=time.time(), updated_at=time.time())
                roster.queue_close_locked(item, "cold_start_terminal_reconcile")
            return bool(term)
        if roster.transact(mutate): found += 1
    roster.audit("cold_start_reconcile", candidates=len(active), terminal_recovered=found)


def prune_native_roster(roster: NativeRoster) -> None:
    """Drop terminal native agents older than the prune window."""
    cutoff = time.time() - ROSTER_PRUNE_AFTER_S
    def mutate(value):
        agents = value.setdefault("agents", {})
        doomed = []
        for agent_id, item in agents.items():
            if not isinstance(item, dict) or item.get("status") not in ("terminal", "lost"):
                continue
            stamp = item.get("stopped_at") or item.get("updated_at") or 0
            try:
                stamp = float(stamp)
            except (TypeError, ValueError):
                continue
            if stamp and stamp < cutoff:
                doomed.append(agent_id)
        for agent_id in doomed:
            agents.pop(agent_id, None)
        return len(doomed)
    dropped = roster.transact(mutate)
    if dropped:
        roster.audit("native_roster_pruned", dropped=dropped)


def prune_exec_roster(roster: NativeRoster) -> None:
    """Drop terminal exec jobs older than the prune window."""
    path = roster.root / "exec_roster.json"
    lock_path = roster.root / ".exec_roster.lock"
    cutoff = time.time() - ROSTER_PRUNE_AFTER_S
    with lock(lock_path):
        doc = read_json(path, {"schema": "codex-loop-exec-roster/v2", "jobs": {}})
        jobs = doc.get("jobs") or {}
        kept, dropped = {}, 0
        for packet_id, item in jobs.items():
            if not isinstance(item, dict):
                continue
            if item.get("state") in ("starting", "running"):
                kept[packet_id] = item
                continue
            stamp = item.get("updated_at") or item.get("started_at") or 0
            try:
                stamp = float(stamp)
            except (TypeError, ValueError):
                stamp = 0.0
            if stamp and stamp < cutoff:
                dropped += 1
            else:
                kept[packet_id] = item
        if dropped:
            doc["jobs"] = kept
            doc["updated_at"] = time.time()
            atomic_json(path, doc)
    if dropped:
        roster.audit("exec_roster_pruned", kept=len(kept), dropped=dropped)


def process_matches(pid: Any, expected_start_ticks: Any = None) -> bool:
    if os.name == "nt":
        try:
            pid = int(pid)
        except (TypeError, ValueError):
            return False
        query = 0x1000  # PROCESS_QUERY_LIMITED_INFORMATION
        handle = ctypes.windll.kernel32.OpenProcess(query, False, pid)
        if not handle:
            return False
        try:
            exit_code = wintypes.DWORD()
            if not ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code)):
                return False
            if exit_code.value != 259:  # STILL_ACTIVE
                return False
            if expected_start_ticks is None:
                return True
            creation = wintypes.FILETIME()
            exit_time = wintypes.FILETIME()
            kernel = wintypes.FILETIME()
            user = wintypes.FILETIME()
            if not ctypes.windll.kernel32.GetProcessTimes(
                    handle, ctypes.byref(creation), ctypes.byref(exit_time),
                    ctypes.byref(kernel), ctypes.byref(user)):
                return False
            actual = (int(creation.dwHighDateTime) << 32) | int(creation.dwLowDateTime)
            return actual == int(expected_start_ticks)
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    try:
        pid = int(pid)
        os.kill(pid, 0)
    except (OSError, TypeError, ValueError):
        return False
    if expected_start_ticks is not None:
        try:
            actual = int(Path("/proc/%d/stat" % pid).read_text(encoding="ascii").split()[21])
            return actual == int(expected_start_ticks)
        except (OSError, ValueError, IndexError):
            return False
    return True


def cold_reconcile_exec(roster: NativeRoster) -> None:
    path = roster.root / "exec_roster.json"
    lock_path = roster.root / ".exec_roster.lock"
    candidates: list[dict[str, Any]] = []
    with lock(lock_path):
        doc = read_json(path, {"schema": "codex-loop-exec-roster/v2", "jobs": {}})
        for packet_id, item in doc.get("jobs", {}).items():
            if item.get("state") not in ("starting", "running"):
                continue
            if process_matches(item.get("supervisor_pid"), item.get("supervisor_proc_start_ticks")):
                continue
            candidates.append({"packet_id": packet_id, **dict(item)})

    terminal: list[dict[str, Any]] = []
    cleanup_failed: list[dict[str, Any]] = []
    for item in candidates:
        # Windows Job Objects kill on supervisor-handle close.  POSIX has no
        # equivalent, so a cold start reaps the still-owned process group.
        cleaned = os.name == "nt"
        if not cleaned:
            try:
                worker_pid = int(item.get("os_pid"))
                proc_path = Path("/proc/%d/stat" % worker_pid)
                # If the former leader PID has already been reused, never
                # signal that unrelated process group.  Its old identity is
                # already gone, so no owned live generation remains.
                if proc_path.exists() and not process_matches(
                        worker_pid, item.get("worker_proc_start_ticks")):
                    cleaned = True
                else:
                    os.killpg(worker_pid, 15)
                    time.sleep(0.05)
                    os.killpg(worker_pid, 9)
                    deadline = time.monotonic() + 0.5
                    while True:
                        try:
                            os.killpg(worker_pid, 0)
                        except ProcessLookupError:
                            cleaned = True
                            break
                        if time.monotonic() >= deadline:
                            break
                        time.sleep(0.02)
            except ProcessLookupError:
                cleaned = True
            except (OSError, TypeError, ValueError):
                cleaned = False

        # Recheck the exact generation under the roster lock.  A concurrent
        # supervisor heartbeat/replacement must never be overwritten by this
        # cold-start observation.
        with lock(lock_path):
            doc = read_json(path, {"schema": "codex-loop-exec-roster/v2", "jobs": {}})
            current = (doc.get("jobs") or {}).get(str(item["packet_id"]))
            if (not isinstance(current, dict)
                    or current.get("run_id") != item.get("run_id")
                    or current.get("state") not in ("starting", "running")
                    or process_matches(current.get("supervisor_pid"),
                                       current.get("supervisor_proc_start_ticks"))):
                continue
            now = time.time()
            if cleaned:
                current.update(state="lost", stop_reason="supervisor_lost",
                               cleanup_status="confirmed_gone", updated_at=now)
                current.setdefault("history", []).append({
                    "ts": now, "state": "lost", "run_id": current.get("run_id"),
                    "attempt": current.get("attempt")})
                terminal.append({"packet_id": item["packet_id"], **dict(current)})
            else:
                # Preserve the active reservation and suppress refill until a
                # later reconcile can prove the old process group is gone.
                current.update(cleanup_status="cleanup_failed_live",
                               cleanup_failed_at=now, updated_at=now)
                cleanup_failed.append({"packet_id": item["packet_id"], **dict(current)})
            atomic_json(path, doc)

    for item in terminal:
        roster.exec_event_once(str(item["packet_id"]), str(item.get("run_id") or "legacy"),
            int(item.get("attempt", 0) or 0), "exec_failed", why="supervisor_lost",
            cancelled=False, cold_start=True)
    roster.audit("cold_start_exec_reconcile", candidates=len(candidates),
                 lost=len(terminal), cleanup_failed=len(cleanup_failed))


def handle(event: str, payload: dict[str, Any], sessions: Path | None = None) -> None:
    roster = NativeRoster(data_dir())
    if event == "PreToolUse": pre_tool(roster, payload)
    elif event == "SubagentStart": subagent_start(roster, payload)
    elif event == "SubagentStop": subagent_stop(roster, payload)
    elif event == "Stop": parent_stop(roster, payload)
    elif event == "SessionStart":
        cold_reconcile(roster, sessions or Path(os.environ.get("CODEX_SESSIONS_DIR", str(Path.home() / ".codex" / "sessions"))))
        cold_reconcile_exec(roster)
        prune_native_roster(roster)
        prune_exec_roster(roster)
        recompute_refill()
        schedule_refill_actuator(project_root(), source="desktop_session_start")
    if event in ("SessionStart", "SubagentStop", "Stop"):
        refresh_meter()


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--event", choices=["PreToolUse", "SubagentStart", "SubagentStop", "Stop", "SessionStart"])
    ap.add_argument("--sessions", type=Path)
    args = ap.parse_args()
    try:
        raw = sys.stdin.read()
        payload = json.loads(raw) if raw.strip() else {}
        event = args.event or payload.get("hook_event_name")
        if event: handle(str(event), payload, args.sessions)
    except BaseException as exc:
        try:
            NativeRoster(data_dir()).audit("hook_degraded", error="%s: %s" % (type(exc).__name__, exc))
        except BaseException:
            pass
    # Stop/SubagentStop require JSON on successful exit; one harmless object
    # also keeps the other command-hook events version-tolerant.
    sys.stdout.write("{}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env sh
# ============================================================================
# subagent_start_meter.sh — SubagentStart metering hook
# Purpose : append one single-line JSON record per subagent spawn to
#           data/events.ndjson (fail-visible routing health observation;
#           the 25x price differential between tiers makes `model` a
#           non-forgeable routing signal)
# Input   : SubagentStart hook payload as one JSON object on stdin
#           (fields used: model, cwd, agent_type, agent_id, turn_id,
#            session_id, permission_mode)
# Output  : one NDJSON line appended to $LOOP_DATA_DIR/events.ndjson
#           {"event":"SubagentStart","ts_utc":...,"model":...,"cwd":...,
#            "agent_role":...,"agent_id":...,"turn_id":...,"session_id":...,
#            "permission_mode":...}
# Safety  : FAIL-OPEN — this hook is pure observation (spec §10 S4). It must
#           NEVER block a spawn: every failure path exits 0. SubagentStart
#           cannot block spawns at the platform level either; events.ndjson
#           is only the fast path — report files are the second truth source.
# Lines   : ~55
# ============================================================================

# Everything is wrapped so that any error still results in exit 0.
{
  # Data directory: repo-local data/ by default, overridable for tests.
  DATA_DIR="${LOOP_DATA_DIR:-data}"
  OUT_FILE="${DATA_DIR}/events.ndjson"

  # Read the entire stdin payload (single JSON object).
  PAYLOAD="$(cat 2>/dev/null || true)"

  # UTC timestamp, ISO-8601 with seconds.
  TS_UTC="$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo unknown)"

  mkdir -p "$DATA_DIR" 2>/dev/null || true

  LINE=""
  if command -v jq >/dev/null 2>&1 && [ -n "$PAYLOAD" ]; then
    # Preferred path: jq guarantees valid, single-line, properly escaped JSON.
    LINE="$(printf '%s' "$PAYLOAD" | jq -c --arg ts "$TS_UTC" '{
      event: "SubagentStart",
      ts_utc: $ts,
      model: (.model // "unknown"),
      cwd: (.cwd // "unknown"),
      agent_role: (.agent_type // "unknown"),
      agent_id: (.agent_id // null),
      turn_id: (.turn_id // null),
      session_id: (.session_id // null),
      permission_mode: (.permission_mode // null)
    }' 2>/dev/null || true)"
  fi

  if [ -z "$LINE" ]; then
    # Degraded path (no jq, empty payload, or malformed JSON): emit a minimal
    # well-formed line so the metering stream never silently gaps. Raw payload
    # is NOT embedded (unescaped JSON-in-JSON would corrupt the NDJSON stream).
    LINE="$(printf '{"event":"SubagentStart","ts_utc":"%s","model":"unknown","cwd":"unknown","agent_role":"unknown","degraded":true}' "$TS_UTC")"
  fi

  printf '%s\n' "$LINE" >> "$OUT_FILE" 2>/dev/null || true
} 2>/dev/null

# Fail-open invariant: unconditional success so the spawn is never impeded
# and the hook is never marked failed for transient metering issues.
exit 0

